def validate_reference_data() -> None:
    if set(PAPER_SURFACES) != {
        "crust",
        "alphatrans",
        "repotransbench",
        "rustrepotrans",
        "sactor",
    }:
        raise ValueError("paper surface catalog drifted")
    if set(REFERENCE_TABLES) != set(PAPER_SURFACES):
        raise ValueError("paper reference table catalog drifted")
    if len(REFERENCE_TABLES["crust"]["paper_table5_error_breakdown.csv"]) != 25:
        raise ValueError("CRUST Table 5 reference drifted")
    if len(REFERENCE_TABLES["alphatrans"]["paper_table2_rq1_summary.csv"]) != 11:
        raise ValueError("AlphaTrans Table 2 reference drifted")
    if len(REFERENCE_TABLES["repotransbench"]["paper_table4_method_comparison.csv"]) != 24:
        raise ValueError("RepoTransBench Table IV reference drifted")


validate_reference_data()
